export type ParsedRolloverFixedTermBorrowInstruction<
  TProgram extends string = typeof KAMINO_LENDING_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    rolloverAccountsPayer: TAccountMetas[0];
    rolloverAccountsObligation: TAccountMetas[1];
    rolloverAccountsLendingMarket: TAccountMetas[2];
    rolloverAccountsLendingMarketAuthority: TAccountMetas[3];
    rolloverAccountsSourceBorrowReserve: TAccountMetas[4];
    rolloverAccountsTargetBorrowReserve: TAccountMetas[5];
    rolloverAccountsLiquidityMint: TAccountMetas[6];
    rolloverAccountsSourceBorrowReserveLiquidity: TAccountMetas[7];
    rolloverAccountsTargetBorrowReserveLiquidity: TAccountMetas[8];
    rolloverAccountsTokenProgram: TAccountMetas[9];
    sourceFarmsAccountsObligationFarmUserState?: TAccountMetas[10] | undefined;
    sourceFarmsAccountsReserveFarmState?: TAccountMetas[11] | undefined;
    targetFarmsAccountsObligationFarmUserState?: TAccountMetas[12] | undefined;
    targetFarmsAccountsReserveFarmState?: TAccountMetas[13] | undefined;
    farmsProgram: TAccountMetas[14];
  };
  data: RolloverFixedTermBorrowInstructionData;
};

export function parseRolloverFixedTermBorrowInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedRolloverFixedTermBorrowInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 15) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 15,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === KAMINO_LENDING_PROGRAM_ADDRESS ? undefined : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      rolloverAccountsPayer: getNextAccount(),
      rolloverAccountsObligation: getNextAccount(),
      rolloverAccountsLendingMarket: getNextAccount(),
      rolloverAccountsLendingMarketAuthority: getNextAccount(),
      rolloverAccountsSourceBorrowReserve: getNextAccount(),
      rolloverAccountsTargetBorrowReserve: getNextAccount(),
      rolloverAccountsLiquidityMint: getNextAccount(),
      rolloverAccountsSourceBorrowReserveLiquidity: getNextAccount(),
      rolloverAccountsTargetBorrowReserveLiquidity: getNextAccount(),
      rolloverAccountsTokenProgram: getNextAccount(),
      sourceFarmsAccountsObligationFarmUserState: getNextOptionalAccount(),
      sourceFarmsAccountsReserveFarmState: getNextOptionalAccount(),
      targetFarmsAccountsObligationFarmUserState: getNextOptionalAccount(),
      targetFarmsAccountsReserveFarmState: getNextOptionalAccount(),
      farmsProgram: getNextAccount(),
    },
    data: getRolloverFixedTermBorrowInstructionDataDecoder().decode(instruction.data),
  };
}
